import type { Player } from './index';

export const squad: Player[] = [
  // Porteros
  { number: 1, name: 'Ørjan Håskjold Nyland', position: 'GK', age: 35, club: 'Sevilla', bio: {"es":"Puede que no sea el miembro más famoso de la selección noruega, pero Nyland es uno de los que lleva más años en servicio y es tranquilo y confiable. Debutó contra Escocia en noviembre de 2013 y ha sido la primera opción durante los últimos cinco años. Antes de eso, Nyland era un atleta polifacético que se destacó en otros deportes. Además de estar entre los mejores porteros del país tanto en fútbol como en balonmano, a los 13 años formó parte de la selección nacional de esquí alpino. \"Había un tira y afloja y una competencia feroz para Ørjan, especialmente entre los equipos de fútbol y balonmano. Todos lo querían y todos tenían que tenerlo\", dijo su padre, Jostein. Nyland ha tenido que lidiar con ser portero suplente en varios de sus clubes y el año pasado ha sido titular en más partidos con Noruega que con el Sevilla.","en":"He may not be the most famous member of the Norwegian national team, but Nyland is one of the longest serving and is calm and reliable. He made his debut against Scotland back in November 2013 and has been the first choice for the past five years. Before that, Nyland was a multitalented athlete who excelled in other sports. In addition to being among the country's best goalkeeping talents in both football and handball, he was on the national alpine skiing team at the age of 13. \"There was a tug-of-war and fierce competition for Ørjan, especially between the football and handball teams. Everyone wanted him, and everyone had to have him,\" his father, Jostein, has said. Nyland has had to contend with being a back-up goalkeeper at several of his clubs and in the past year he has started more matches for Norway than Sevilla."}, special: "No 1 goalkeeper" },
  { number: 12, name: 'Sander Tangvik', position: 'GK', age: 23, club: 'Hamburg', bio: {"es":"Tangvik ha sido visto como el futuro portero titular de Noruega durante varios años. Con sólo 23 años, disputó 85 partidos con el Rosenborg antes de fichar por el Hamburgo en enero. Tiene tremendos reflejos y es un muy buen taponador, lo que explica en parte su excelente desempeño en los penaltis: en el momento de escribir este artículo ha salvado uno de cada tres penaltis que ha afrontado. Como corresponde a un portero moderno, también es muy bueno con los pies, ya que creció con Pepe Reina como modelo a seguir. Es poco probable que Tangvik tenga tiempo de juego en la Copa del Mundo, pero ser parte del equipo será una experiencia valiosa. En 2025, recibió un golpe en la nariz y sangró profusamente, pero el médico del equipo Rosenborg le cosió la herida y siguió adelante. \"Esta es la Eliteserien, debería haber algunos golpes durante un partido, especialmente contra Bryne\", dijo.","en":"Tangvik has been seen as Norway’s future first-choice goalkeeper for several years. Still only 23, he made 85 appearances for Rosenborg before joining Hamburg in January. He has tremendous reflexes and is a very good shot-stopper, which goes some way to explain his excellent record with penalties: at the time of writing he has saved every third spot-kick he has faced. As befits a modern goalkeeper he is also very good with his feet, having grown up with Pepe Reina as his role model. Tangvik is unlikely to get any playing time at the World Cup but being part of the squad will be a valuable experience. In 2025, he got a knock on his nose and bled profusely but the Rosenborg team doctor stitched the wound together and he carried on. “This is the Eliteserien, there should be some knocks during a game, especially against Bryne,” he said."} },
  { number: 13, name: 'Egil Selvik', position: 'GK', age: 28, club: 'Watford', bio: {"es":"La historia de Selvik es un poco inusual. Cuando fichó por el FK Haugesund en 2021, tenía 23 años y solo había jugado un partido de la primera división en Noruega. Pero muy rápidamente se consagró como uno de los mejores porteros del país. Ahora, con 28 años, está viviendo el sueño profesional en Inglaterra jugando para Watford, donde es el número uno del club. A nivel internacional ha sido suplente de Ørjan Håskjold Nyland durante varios años, pero debido al tiempo limitado de juego de Nyland en el Sevilla, ha habido sugerencias de que Selvik podría ser titular en la Copa del Mundo. Pasó parte de su infancia en Aberdeen mientras su padre trabajaba en Escocia en la industria petrolera, aprendiendo inglés mientras asistía a la escuela primaria. Cuando llegó al Watford, admitió que le había llevado algún tiempo acostumbrarse a su nuevo coche. \"Lo encuentro muy diferente. Si voy en piloto automático, normalmente entro por el lado izquierdo, ¡y luego recuerdo que el volante está en el lado derecho! Estoy seguro de que me acostumbraré\", dijo al sitio web de Watford.","en":"Selvik’s story is a bit unusual. By the time he signed for FK Haugesund in 2021, he was 23 years old and had played only one top division match in Norway. But very quickly he established himself as one of the very best goalkeepers in the country. Now 28, he is living the professional dream in England playing for Watford, where he is the club’s No 1. At international level he has been back-up to Ørjan Håskjold Nyland for several years but because of Nyland’s limited playing time at Sevilla, there have been suggestions Selvik may start at the World Cup. Spent part of his childhood in Aberdeen as his father worked in Scotland in the oil industry, learning English while attending primary school. When he joined Watford he admitted it had taken some time to get used to his new car. “I find it very different. If I go on autopilot, I usually enter on the left side – and then I remember the steering wheel is on the right side! I’m sure I will get used to it,” he told the Watford website."} },
  // Defensores
  { number: 3, name: 'Kristoffer Ajer', position: 'DF', age: 28, club: 'Brentford', bio: {"es":"Si sigues la Premier League, probablemente habrás notado que los saques de banda largos se han vuelto populares. Brentford usa esta arma con gran efecto y, a menudo, el balón se lanza a la cabeza de un tipo noruego alto, quien lo lanza hacia la portería del oponente. Con 1,98 m, Ajer es el jugador de campo más alto de su club y de la selección nacional, y una amenaza en las jugadas a balón parado. Cuando era joven, Ajer era tan bueno en la escuela como en el fútbol y a menudo obtenía las notas más altas, un gran contraste con la forma en que los medios juzgaron su actuación en el primer partido de Ståle Solbakken al mando de Noruega, una derrota por 3-0 ante Turquía. La mayoría de la gente le dio a Ajer un 2 sobre 10. \"La valoración del jugador era merecida. Jugué muy mal\", admitió más tarde. Las cosas han mejorado para el jugador de 28 años desde entonces y el año pasado se estableció como líder de la defensa noruega, papel que desempeñará en la Copa del Mundo.","en":"If you follow the Premier League, you have probably noticed that long throw-ins have become popular. Brentford use this weapon to great effect and often the ball is launched on to the head of a tall Norwegian bloke, who flicks it on towards the opponent’s goal. At 1.98m, Ajer is the tallest outfield player for his club and the national team – and a threat at set pieces. As a youngster, Ajer was as good at school as he was at football and often got the highest grades – a big contrast to how the media judged his performance in Ståle Solbakken’s first game in charge for Norway, a 3-0 defeat by Turkey. Ajer was given a 2 out 10 by most people. \"The player rating was deserved. I played really bad,\" he admitted later. Things have looked up for the 28-year-old since then and last year he established himself as the leader of the Norwegian defence – a role he will have at the World Cup."}, special: "Defensive leader" },
  { number: 4, name: 'Leo Østigård', position: 'DF', age: 26, club: 'Genoa', bio: {"es":"Østigård es uno de los jugadores más bajos del equipo, pero quizás sea el mejor cabeceador. \"Mi padre y yo hemos practicado mucho cabecear. He cabeceado un balón desde que tenía tres años, así que a estas alturas ya debería ser bueno haciéndolo\", dijo Østigård a NRK Sport. Desde el principio hubo señales de que el chico de la pequeña ciudad de Åndalsnes, en la costa oeste, estaba destinado a convertirse en un gran defensor. Vio su primer Mundial en 2006 y un jugador en particular le impresionó. \"Fabio Cannavaro no es el más alto, pero estaba 'loco' de la cabeza y ganaba todos los duelos. Me inspiró\". Sorprendentemente, Østigård se unió a uno de los antiguos clubes de Cannavaro, el Napoli, en 2022 y ganó el Scudetto al año siguiente. Con Noruega, Østigård perdió su puesto de titular en 2025 después de algunos errores costosos, pero es un luchador y hará todo lo posible para recuperar su lugar en el equipo.","en":"Østigård is among the shortest players on the team, yet he is perhaps the best header of the ball. \"My father and I have practised heading a lot. I've been heading a ball since I was three years old, so by now I should be good at it,\" Østigård told NRK Sport. There were signs early on that the boy from the small town of Åndalsnes on the west coast was destined to become a top defender. He watched his first World Cup in 2006 and one player in particular made an impression on him. \"Fabio Cannavaro isn't the tallest, but he was 'crazy' in the head and won every duel. He inspired me.\" Remarkably, Østigård went on to join one of Cannavaro’s former clubs, Napoli, in 2022 and won the Scudetto the following year. With Norway, Østigård lost his starting place in 2025 after some costly mistakes but he is a fighter and he will do anything he can to reclaim his place in the team."}, special: "Strong in the air" },
  { number: 5, name: 'David Møller Wolfe', position: 'DF', age: 24, club: 'Wolves', bio: {"es":"David Møller Wolfe es la prueba viviente de que no es necesario unirse temprano a una academia para llegar a la Premier League. Mientras que la mayoría de los mejores talentos del área de Bergen se unieron al club principal de la ciudad, Brann, temprano, Møller Wolfe, optó por quedarse en el club de su infancia, Bergen Nord, todo el tiempo que pudo. Todavía jugaba en la quinta división de Noruega cuando lo eligieron para la selección nacional sub-17. El lateral izquierdo veloz y ofensivo creció en España, pero regresó a Bergen cuando tenía 11 años. Fue en España donde se enamoró del fútbol. Con el tiempo, desarrolló tanto que se unió al Brann, donde ganó la Copa de Noruega, antes de ser vendido al AZ. El verano pasado, Wolfe cumplió su destino al unirse a los Wolves por £10 millones.","en":"David Møller Wolfe is living proof that you don’t have to join an academy early to reach the Premier League. While most of the best talents from the Bergen area joined the city’s main club, Brann, early, Møller Wolfe, chose to stay with his childhood club Bergen Nord for as long as he could. He was still playing in the fifth tier in Norway when he was being picked for the Under-17 national team. The lightning-fast and attacking left-back grew up in Spain but moved back home to Bergen when he was 11 years old. It was in Spain he fell in love with football. Eventually, he developed so much that he joined Brann, where he won the Norwegian Cup, before being sold to AZ. Last summer, Wolfe fulfilled his destiny by joining Wolves for £10m."} },
  { number: 15, name: 'Fredrik André Bjørkan', position: 'DF', age: 27, club: 'Bodø/Glimt', bio: {"es":"Bjørkan sabe lo que significa la palabra presión. El lateral izquierdo atacante creció en Bodø, un lugar que ahora Bodø/Glimt ha puesto en el mapa. Allí viven unas 50.000 personas y Bjørkan creció como hijo de uno de los más famosos entre ellos. Su padre, Aasmund Bjørkan, es una leyenda en Bodø/Glimt y, cuando Fredrik era lo suficientemente bueno y mayor para formar parte del primer equipo, su padre era el entrenador del club. En una entrevista con el periódico VG, Aasmund dijo que cuando su hijo jugaba mal, escuchaba rumores de que Fredrik solo jugaba porque su padre era el entrenador. \"Me pareció una situación muy difícil\", dijo Aasmund. \"Especialmente en 2016. Hubo varias ocasiones en las que no lo elegí porque no podía soportar tanta charla. Pero definitivamente era lo suficientemente bueno incluso entonces\". Llega a la Copa del Mundo habiendo sido parte del increíble viaje de Bodø/Glimt a la Liga de Campeones en 2025-26.","en":"Bjørkan knows what the word pressure means. The attacking left-back grew up in Bodø, a place that has now been put on the map by Bodø/Glimt. About 50,000 people live there and Bjørkan grew up as the son of one of the most famous among them. His father Aasmund Bjørkan is a legend at Bodø/Glimt and, when Fredrik was good enough and old enough to become a part of the first team, his father was the club’s coach. In an interview with the newspaper VG, Aasmund said that when his son had a poor game he could hear the murmurs about Fredrik only playing because his father was the coach. “I found it a very difficult situation,” Aasmund said. “Especially in 2016. There were several times that I didn’t pick him, because I couldn’t stand all the talking. But he was definitely good enough even then.” Arrives at the World Cup having been part of Bodø/Glimt’s incredible Champions League journey in 2025-26."} },
  { number: 16, name: 'Marcus Holmgren Pedersen', position: 'DF', age: 25, club: 'Torino', bio: {"es":"Pedersen ha seguido los pasos de los ex jugadores de la selección nacional y de la Premier League Morten Gamst Pedersen y Stefan Johansen, en el sentido de que todos ellos son modelos a seguir para los niños que crecen en la región más septentrional de Noruega. No es raro que Hammerfest, la ciudad natal de Marcus Holmgren Pedersen, esté cubierta de nieve durante más de la mitad del año. Hammerfest se encuentra a una latitud de 70,6634° y afirma ser la ciudad más septentrional del mundo. Los veranos son cortos y los inviernos muy largos. Desde el sol de medianoche en verano hasta inviernos helados, nevados, ventosos y oscuros como boca de lobo. Es el clima noruego en su mejor y peor momento. Pedersen está marcado por las condiciones en las que creció. El lateral derecho es duro en el campo y deja todo ahí afuera. Su viaje lo llevó desde Tromsø en el norte hasta Molde, luego Feyenoord y una cesión en Torino, antes de un cambio permanente al club de la Serie A en 2025.","en":"Pedersen has followed in the footsteps of former national team and Premier League players Morten Gamst Pedersen and Stefan Johansen, in that they are all role models for children growing up in Norway’s northernmost region. It is not unusual for Marcus Holmgren Pedersen’s hometown, Hammerfest, to be snow-covered for more than half the year. Hammerfest is located at a latitude of 70.6634° and claims to be the world’s northernmost city. The summers are short, and the winters very long. From midnight sun in the summer to freezing, snowy, windy and pitch-black winters. It is the Norwegian climate at its best and worst. Pedersen is shaped by the conditions he grew up in. The right-back is tough on the pitch and leaves everything out there. His journey has taken him from Tromsø in the north to Molde then Feyenoord and a loan at Torino, before a permanent switch to the Serie A club in 2025."}, special: "Fighter" },
  { number: 17, name: 'Torbjørn Heggem', position: 'DF', age: 26, club: 'Bologna', bio: {"es":"\"Solía ​​decirme a mí mismo que se necesitan 10.000 horas para ser bueno en algo\", dijo una vez Heggem a TV2 y vivió según esta idea mientras crecía. Sin embargo, si entrenas “sólo” una hora al día, tardarás más de 27 años en alcanzar esa meta, y es poco probable que hayas comenzado desde el primer día. Heggem no tuvo 27 años para conseguir lo que quería así que se entrenó todo lo que pudo y en tantas disciplinas como le fue posible, todo con el objetivo de convertirse en futbolista profesional. Practicaba esquí de fondo, salto de longitud y lanzamiento de jabalina, pero siempre tenía una pelota de fútbol a mano. Su padre, Trond, ha dicho que a menudo pensaba: “Si Torbjørn no se convierte en atleta, entonces no entenderé nada”. El resultado de este entrenamiento específico es un central de 1,92 m que rara vez pierde una carrera en el campo y es casi imbatible en el aire.","en":"“I used to tell myself that it takes 10,000 hours to become good at something,” Heggem once told TV2 and he lived by this idea growing up. However, if you train for “only” one hour a day it takes more than 27 years to reach that – and you are unlikely to have started from day one. Heggem didn’t have 27 years to get to what he wanted so he trained as much as he could and in as many disciplines as possible, all with the aim of becoming a professional footballer. He did cross-country skiing, long jump and javelin – but always had a football nearby. His father, Trond, has said that he often thought: “If Torbjørn doesn’t become an athlete, then I won’t understand anything.” The result of this targeted training is a 1.92m centre-back who rarely loses a foot race on the pitch and is almost unbeatable in the air."} },
  { number: 24, name: 'Sondre Langås', position: 'DF', age: 25, club: 'Derby County', bio: {"es":"Hace tres años Langås jugaba en la segunda división noruega con el Ranheim. Tenía 22 años y no había representado a ninguno de los equipos juveniles noruegos. Es justo decir que era relativamente desconocido. Sin embargo, en el verano de 2023, el club Viking de primera categoría lo contrató y 18 meses después hizo su debut en Noruega y se mudó al Derby por £ 4,5 millones. Langås capitaneaba el equipo del campeonato cuando sufrió una lesión en el tendón de la corva en enero. En una entrevista con el canal de televisión Viaplay, el entrenador de Noruega, Ståle Solbakken, dijo: \"Tiene que salir al campo y pasar un mes de abril muy bueno si quiere subirse a ese avión hacia la Copa del Mundo\". Al final logró precisamente eso. Jugador de balonmano con mucho talento, lo compaginó con el fútbol hasta los 18 años.","en":"Three years ago Langås was playing in the second tier in Norway for Ranheim. He was 22 years old and had not represented any of the Norwegian youth teams. It is fair to say that he was relatively unknown. However in the summer of 2023, the top-flight club Viking signed him and 18 months later he made his Norway debut and moved to Derby for £4.5m. Langås was captaining the Championship side when he suffered a hamstring injury in January. In an interview with the TV channel Viaplay, Norway’s head coach, Ståle Solbakken, said: “He has to get on the pitch and have a very good month in April if he is to get on that plane to the World Cup.” In the end he managed just that. A very talented handball player, he combined it with football until the age of 18."} },
  { number: 25, name: 'Henrik Falchener', position: 'DF', age: 22, club: 'Viking', bio: {"es":"Falchener admitió que derramó algunas lágrimas después de su impactante inclusión por parte de Ståle Solbakken. \"Nunca pensé que esto sucedería tan rápido. Realmente no tengo palabras\", dijo a TV2. El jugador de 23 años solo jugó un partido internacional y fue en marzo, después de que Noruega se clasificara para la Copa del Mundo. El camino hacia la cima ha sido largo para Falchener, aunque en los últimos años ha ido muy rápido. Después de ser expulsado de una academia a la edad de 16 años, se fue a Sandefjord, pero tuvo problemas para ganar tiempo de juego, lo que lo hizo descender al tercer nivel. Finalmente consiguió un pase al Viking e inmediatamente se convirtió en uno de los mejores defensores de la máxima categoría, quizás el mejor. El central también contribuyó en el otro extremo, anotando seis goles cuando el Viking ganó la Eliteserien 2025 en su primera temporada en el club.","en":"Falchener admitted he shed a few tears after his shock inclusion by Ståle Solbakken. “I never thought it would happen so quickly. I really have no words,” he told TV2. The 23-year-old only had one cap to his name and it came in March, after Norway had qualified for the World Cup. The road to the top has been long for Falchener, although it has gone very quickly in recent years. After being rejected from an academy at the age of 16, he went on to Sandefjord but struggled for playing time, which made him drop down to the third tier. He eventually landed a move to Viking and immediately became one of the best defenders in the top flight, perhaps the very best. The centre-back has contributed up the other end too, scoring six times as Viking won the 2025 Eliteserien in his first season at the club."}, special: "Surprise call-up" },
  { number: 26, name: 'Julian Ryerson', position: 'DF', age: 28, club: 'Borussia Dortmund', bio: {"es":"Ryerson es lo más parecido a un arma suelta en el equipo de Noruega. \"Preferiría no comentar sobre su cerebro... las cosas que suceden allí no son normales\", dijo una vez con una sonrisa el seleccionador de Noruega, Ståle Solbakken, antes de añadir: \"pero eso es bueno\". Se refería a las cualidades especiales que han llevado a Ryerson a la cima: valentía, concentración y amor por los tackles a la antigua usanza. Tras dejar el Viking por el Union Berlin en 2018, permaneció en la capital de Alemania durante cinco años antes de unirse al Borussia Dortmund, donde una de sus mejores actuaciones fue contra el PSG en las semifinales de la Liga de Campeones 2023-24. La defensa del Dortmund mantuvo tranquilos a Kylian Mbappé, Bradley Barcola y Ousmane Dembélé, sin encajar goles en ninguno de los partidos. \"No teníamos ningún plan especial para detener a Mbappé\", dijo Ryerson después. \"También tenían a Dembélé y al otro chico, no sé su nombre [Barcola]. Teníamos que ser los mejores uno contra uno, y lo fuimos\". Esa mentalidad le resultará útil cuando Ryerson se enfrente una vez más a las superestrellas francesas en la Copa del Mundo.","en":"Ryerson is the closest thing to a loose cannon in the Norway squad. “I would rather not comment on his brain ... the things that go on in there are not normal,” the Norway coach, Ståle Solbakken, once said with a smile, before adding: “but that is good.” He was referring to the special qualities that have taken Ryerson to the very top: fearlessness, focus and the love for an old-fashioned tackle. Having left Viking for Union Berlin in 2018 he stayed in Germany’s capital for five years before joining Borussia Dortmund, where one of his finest performances came against PSG in the 2023-24 Champions League semi-finals. Dortmund’s defence kept Kylian Mbappé, Bradley Barcola and Ousmane Dembélé quiet, not conceding in either leg. “We had no special plan to stop Mbappé,” Ryerson said afterwards. “They also had Dembélé and the other guy, I don’t know his name [Barcola]. We had to be best one v one, and we were.” That mindset will come in handy when Ryerson once again faces the French superstars at the World Cup."}, special: "Maverick" },
  // Volantes
  { number: 2, name: 'Morten Thorsby', position: 'MF', age: 30, club: 'Cremonese', bio: {"es":"Thorsby es un guerrero del mediocampo y los oponentes no deben dejarse engañar por su apariencia amable.\nEn el fútbol, ​​la camiseta número 2 la lleva tradicionalmente el lateral derecho, pero el número 2 de Noruega no es en absoluto tradicional. Thorsby ha dedicado la mayor parte de su vida adulta a la lucha contra el cambio climático y el calentamiento global. El número de su camiseta hace referencia al objetivo internacional de limitar el aumento de la temperatura media global por debajo de los 2 grados centígrados. En 2022, Thorsby fue nombrado embajador del Pacto Europeo por el Clima. Normalmente va en bicicleta a entrenar y, si es posible, viaja en tren en lugar de en avión. Cuando estaba en Heerenveen, Thorsby convenció al club para que invirtiera en paneles solares en el techo del estadio. Cuando se le preguntó qué pensaba sobre el difícil grupo de Noruega en la Copa del Mundo, respondió centrándose en las ubicaciones de Boston y Nueva York: \"Estoy feliz porque no tenemos que volar tanto\". Si ves a Noruega llegar al estadio del Mundial en autobús eléctrico, ya sabes por qué.","en":"Thorsby is a midfield warrior and opponents should not be fooled by his gentle appearance.\nIn football, the No 2 shirt is traditionally worn by the right-back but Norway’s No 2 is by no means traditional. Thorsby has dedicated most of his adult life to the fight against climate change and global heating. His shirt number refers to the international goal of limiting the increase in global average temperature to below 2 degrees celsius. In 2022 Thorsby was appointed a European Climate Pact ambassador. He normally takes his bike to training and, if possible, travels by train rather than plane. When at Heerenveen, Thorsby convinced the club to invest in solar panels on the stadium roof. When asked about his thoughts of Norway’s tough World Cup group, he responded by focusing on the locations in Boston and New York: “I’m happy because we don’t have to fly so much.” If you see Norway arriving at the World Cup stadium by electric bus, you now know why."}, special: "Environmentalist" },
  { number: 6, name: 'Patrick Berg', position: 'MF', age: 28, club: 'Bodø/Glimt', bio: {"es":"Hace ocho años, el contrato de Berg en Bodø/Glimt estaba a punto de expirar. Su forma había sido mala y no estaba seguro de su futuro. \"En realidad estaba pensando en dejar el fútbol por completo y buscar otra cosa que hacer\", dijo. Unos meses más tarde acabó firmando un nuevo contrato con Glimt y no ha mirado atrás. Es un centrocampista potente que cubre amplias zonas del campo. Sólo ocho jugadores corrieron más que él en la fase liguera de la Liga de Campeones. El nombre Berg forma parte del mobiliario de Bodø/Glimt. Su abuelo Harald “Dutte” Berg es uno de los mejores jugadores de Noruega. Su padre, Ørjan, jugó 19 partidos con Noruega y sus tíos, Runar y Arild, también fueron futbolistas profesionales. Habiendo decidido quedarse, Patrick Berg se convirtió en capitán y ganó la liga noruega cuatro veces, alcanzó las semifinales de la Europa League y ayudó a sorprender al Manchester City y al Inter en la Liga de Campeones.","en":"Eight years ago Berg’s contract at Bodø/Glimt was expiring. His form had been poor and he was uncertain about his future. “I was actually thinking about quitting football completely and finding something else to do,” he has said. A few months later he ended up signing a new contract with Glimt and has not looked back. He is a powerful midfielder who covers vast areas of the pitch. Only eight players ran more than him in the league phase of the Champions League. The name Berg is part of the furniture at Bodø/Glimt. His grandfather Harald “Dutte” Berg is one of Norway’s greatest players. His father, Ørjan, won 19 caps for Norway and his uncles, Runar and Arild, were also professional footballers. Having decided to stay, Patrick Berg became captain and has now won the Norwegian league four times, reached the semi-finals of the Europa League and helped to stun Manchester City and Inter in the Champions League."} },
  { number: 8, name: 'Sander Berge', position: 'MF', age: 28, club: 'Fulham', bio: {"es":"Te costará encontrar a alguien que tenga algo malo que decir sobre Sander Berge. El centrocampista siempre parece tener una sonrisa en el rostro y hace las cosas, aparentemente, sin ninguna preocupación en el mundo. Sin embargo, la vida en el campo no siempre ha sido fácil para el jugador de 28 años, ya que ha tenido que asumir una gran responsabilidad en el corazón del mediocampo noruego, además de descender con Sheffield United y Burnley. Sin embargo, también ha habido varios éxitos y desde 2025 es un jugador establecido de la Premier League y estuvo entre los mejores jugadores en el campo cuando Noruega se clasificó para la Copa del Mundo. También se convirtió en padre por primera vez. La altura de Berge, que le convierte en una figura imponente en el campo, se debe a su familia: su madre, su padre y su hermano mayor han jugado baloncesto a nivel internacional.","en":"You will struggle to find anyone who has a bad word to say about Sander Berge. The midfielder always seems to have a smile on his face and goes about things, seemingly, without a worry in the world. Yet life on the pitch has not always been easy for the 28-year-old as he has had to shoulder a lot of responsibility at the heart of the Norway midfield, while also being relegated with Sheffield United and Burnley. However, there have been several highs as well and since 2025 he has been an established Premier League player and was among the best players on the pitch as Norway qualified for the World Cup. He also became a father for the first time. Berge's height, which makes him a towering figure on the field, comes via his family: his mother, father and older brother have all played basketball at an international level."}, special: "Infectious personality" },
  { number: 10, name: 'Martin Ødegaard', position: 'MF', age: 27, club: 'Arsenal', captain: true, bio: {"es":"Cuando tenía seis años, Ødegaard pateaba un balón de fútbol a 60 km/h. Jugó su primer partido senior a la edad de 13 años. Dos años más tarde, había dominado la primera división de Noruega hasta tal punto que se convirtió en el niño prodigio más buscado del mundo. Cuando debutó con la selección nacional a la edad de 15 años, la técnica de Ødegaard, su capacidad para leer el juego y dictar el ritmo lo hacían parecer un profesional experimentado. \"Necesité cinco minutos para ver que tenía lo necesario\", dijo el entonces entrenador del Bayern de Múnich, Pep Guardiola. Llegó al Real Madrid en 2015 y debutó como suplente sustituyendo a Cristiano Ronaldo. Sin embargo, su ascenso a la cima no fue lineal y hubo reveses con la selección nacional y cesiones en Heerenveen, Vitesse y Real Sociedad antes de un cambio transformador al Arsenal. Ahora, sin embargo, es el capitán del club y de la selección y dirigirá a Noruega en su primer Mundial desde el año en que nació. Es seguro decir que el niño prodigio se ha convertido en un hombre.","en":"When he was six years old, Ødegaard kicked a football at 60km/h. He played his first senior match at the age of 13. Two years later, he had dominated Norway's top division to such an extent he became the world's most sought-after wonderkid. When he made his debut for the national team at the age of 15, Ødegaard’s technique, ability to read the game and dictate the tempo made him look like a seasoned pro. \"I needed five minutes to see that he has what it takes,\" said the then Bayern Munich manager Pep Guardiola. Having joined Real Madrid in 2015, he made his debut as a substitute, replacing Cristiano Ronaldo. His rise to the top was not linear though and there were setbacks with the national team and loan spells at Heerenveen, Vitesse and Real Sociedad before a transformative move to Arsenal. Now, though, he is the captain for club and country and will lead Norway in their first World Cup since the year he was born. It is safe to say that the wonderkid has become a man."}, special: "A joy to watch" },
  { number: 14, name: 'Fredrik Aursnes', position: 'MF', age: 30, club: 'Benfica', bio: {"es":"Portugal es el mayor mercado para el clipfish noruego (bacalao seco y salado) con una exportación anual aproximada de 350 millones de euros. El ingrediente principal del plato favorito de Cristiano Ronaldo, el bacalhau, proviene de la región de Sunnmøre. Aquí también creció Fredrik Aursnes, el segundo exportador más famoso de Noruega a Portugal. Ha sido influyente para el Benfica desde que llegó en 2022 pero, dos años después, abandonó repentinamente la selección nacional. \"Se volvió demasiado agitado\", dijo. \"Fue una prisa todo el tiempo y sentí como si no pudiera respirar. Estaba mentalmente cansado\". Por lo tanto, fue algo controvertido cuando regresó a sus funciones cuatro meses antes de una Copa del Mundo en la que no había participado. Pero la mayoría de los noruegos están felices de que Aursnes haya regresado. No tiene factor X, pero es funcional y versátil: un verdadero centrocampista polivalente que siempre hace que su equipo sea un poco mejor.","en":"Portugal is the largest market for Norwegian clipfish (dried and salted cod) with an approximate annual export of €350m. The main ingredient in Cristiano Ronaldo’s favourite dish, bacalhau, comes from the Sunnmøre region. This is also where Norway’s second-most famous export to Portugal, Fredrik Aursnes, grew up. He has been influential for Benfica since joining in 2022 but, two years later, he suddenly quit the national team. “It got too hectic,” he said. “It was a rush the whole time, and it felt like I couldn’t breathe. I was mentally tired.” So it was somewhat controversial when he reported back for duty four months before a World Cup he had played no part in reaching. But most Norwegians are happy Aursnes is back. He doesn’t have an X factor but is functional and versatile – a proper all-round midfielder who always makes his team a little bit better."} },
  { number: 18, name: 'Kristian Thorstvedt', position: 'MF', age: 27, club: 'Sassuolo', bio: {"es":"Thorstvedt es un nombre muy conocido en Noruega. El padre de Kristian, Erik, ganó la Copa FA con el Tottenham y jugó en el Mundial de 1994. Puede que Kristian no sea el talento más precoz de su generación, pero es un luchador con olfato para el gol. Thorstvedt se desarrolló tarde físicamente, por lo que, cuando sus mejores amigos firmaron contratos profesionales, decidió estudiar y jugar fútbol universitario en Estados Unidos. Sólo cuando su padre hizo una última llamada a su antiguo club, el Viking, para ver si Kristian podía entrenar con ellos, su carrera despegó. Dos años más tarde ascendió a la Eliteserien, alcanzó cifras dobles en goles, ganó la Copa de Noruega, fue vendido al Genk y debutó en Noruega. \"Nunca pensé que Kristian jugaría para la selección nacional. ¡Nunca!\" ha dicho Erik. Este verano, el dinámico e inteligente centrocampista vuelve a Estados Unidos, pero esta vez para representar a su país y no como estudiante.","en":"Thorstvedt is a household name in Norway. Kristian’s father, Erik, won the FA Cup with Tottenham and played at the 1994 World Cup. Kristian may not be the most precocious talent of his generation but he is a fighter with a nose for goal. Thorstvedt developed late physically so, when his best friends signed professional contracts, he decided to study and play college football in the US. It was only when his father made one last call to his old club, Viking, to see if Kristian could train with them that his career took off. Two years later he was promoted to the Eliteserien, reached double figures in goals, won the Norwegian Cup, was sold to Genk and made his Norway debut. “I never thought that Kristian would play for the national team. Never!” Erik has said. This summer the dynamic and intelligent midfielder goes to the US again – but this time to represent his country rather than as a student."}, special: "Intelligent player" },
  { number: 19, name: 'Thelo Aasgaard', position: 'MF', age: 24, club: 'Rangers', bio: {"es":"Aasgaard llegó como una sorpresa para la mayoría de los noruegos durante las eliminatorias para el Mundial. Nació y creció en Liverpool y nunca vivió en Noruega. Entiende algo de noruego pero prefiere conversar en inglés. A los nueve años ingresó en la academia del Liverpool, donde jugó, entre otros, con Curtis Jones. A través de su padre, tenía derecho a viajar a Noruega. Aasgaard proviene de una familia de músicos. Su padre es un violonchelista de renombre mundial. Su madre también toca el violonchelo y sus dos hermanos son músicos de jazz. Thelo, por su parte, hace música en su tiempo libre para desconectar del fútbol. \"Admiro mucho a mis padres. Tenemos trabajos relacionados, porque a ambos se les juzga por su desempeño. Cuando estoy en un concierto con mi papá, sé la presión que sufre frente a una gran audiencia\".","en":"Aasgaard arrived as a surprise to most Norwegians during the World Cup qualifiers. He was born and raised in Liverpool and has never lived in Norway. He understands some Norwegian but prefers to converse in English. At the age of nine he joined the Liverpool academy, where he played with Curtis Jones among others. Through his father, he was eligible for Norway. Aasgaard comes from a musical family. His father is a world-renowned cellist. His mother also plays the cello, and his two siblings are jazz musicians. Thelo, meanwhile, makes music in his spare time to switch off from football. “I look up to my parents a lot. We have related jobs, because both are judged on performance. When I’m at a concert with my dad, I know the pressure he’s under in front of a large audience.”"} },
  // Delanteros
  { number: 7, name: 'Alexander Sørloth', position: 'FW', age: 31, club: 'Atlético Madrid', bio: {"es":"Durante mucho tiempo, Sørloth fue el oficial que luchaba por asentarse. Antes de cumplir 25 años había jugado en Noruega, Dinamarca, Países Bajos, Inglaterra, Bélgica, Turquía y Alemania. Pocos hubieran pensado que sería en la liga donde el gran y fuerte delantero, que se ganó el apodo de \"Rey del Norte\" entre los aficionados del Trabzonspor, encontraría su lugar. Pero fue en la Real Sociedad, rodeado de jugadores como David Silva, Mikel Merino y Alexander Isak, donde Sørloth realmente logró su avance al más alto nivel. Su padre, Gøran, que formó parte de la selección de Noruega en el Mundial de 1994, era conocido en su país de origen como \"el mejor delantero del mundo de espaldas a la portería\". Alexander también es duro, pero es más peligroso de cara a la portería a toda velocidad. Viene de una buena temporada en el Atlético de Madrid y rara vez tiene un mal partido con Noruega. Es posible que Sørloth pronto se convierta en el segundo lugar detrás de ya sabes quién en la tabla de goleadores de todos los tiempos de Noruega, habiendo superado ya a jugadores como Ole Gunnar Solskjær, Tore André Flo y John Carew.","en":"For a long time Sørloth was the journeyman who struggled to settle down. Before turning 25, he had played in Norway, Denmark, the Netherlands, England, Belgium, Turkey and Germany. Few would have thought that it was in La Liga that the big, strong striker, who earned the nickname \"King of the North\" from Trabzonspor supporters, would find his place. But it was at Real Sociedad, surrounded by players such as David Silva, Mikel Merino and Alexander Isak, that Sørloth truly made his breakthrough at the highest level. His father, Gøran, who was part of Norway's squad at the 1994 World Cup, was known in his home country as \"the world's best striker with his back to goal\". Alexander is also tough, but is most dangerous facing the goal at full speed. He is coming off a fine season at Atlético Madrid and rarely has a bad game for Norway. Sørloth may well soon become second to you-know-who in Norway’s all-time scoring charts, having already surpassed players such as Ole Gunnar Solskjær, Tore André Flo and John Carew."} },
  { number: 9, name: 'Erling Haaland', position: 'FW', age: 25, club: 'Manchester City', bio: {"es":"Parece casi surrealista pensar que uno de los mejores futbolistas del mundo creció en Bryne, una ciudad pequeña y corriente en el suroeste de Noruega. ¿Será porque la gente de allí trabaja más duro para salir adelante? ¿Será que todas las horas que se pasan en el pabellón interior se construyeron porque es difícil jugar al fútbol al aire libre durante todo el año? Quizás sea la leche fresca de las vacas locales. ¿Quizás sea porque Haaland estaba tan obsesionado con el fútbol que veía todos los partidos que podía por televisión e incluso estudiaba la capacidad de Jamie Vardy para permanecer en juego? ¿O es porque su madre era una destacada heptatleta y su padre, Alfie, jugaba en la Premier League? Probablemente sea una mezcla de todo. Lo que es seguro es que la asombrosa cifra de goles de Haaland (convertirse en el máximo goleador de todos los tiempos de su país antes de cumplir 25 años, tres Botas de Oro de la Premier League en cuatro temporadas en el Manchester City, 57 goles en la Liga de Campeones en 58 partidos) lo distingue como un fenómeno y el mejor delantero centro de su era.","en":"It feels almost surreal to think that one of the world’s best footballers grew up in Bryne, a small and unremarkable town in the south-west of Norway. Could it be because people from there work extra hard to get ahead? Is it all the hours spent in the indoor hall that was built because it's difficult to play football outdoors all year round? Maybe it's the fresh milk from the local cows. Perhaps it is because Haaland was so obsessed with football he watched every game he could on TV and even studied Jamie Vardy's ability to stay onside? Or is it because his mother was a prominent heptathlete and his father, Alfie, played in the Premier League? Probably it is a mix of everything. What’s for certain is Haaland’s astonishing goal return – becoming his nation’s all-time top scorer before he turned 25, three Premier League Golden Boots in four seasons at Manchester City, 57 Champions League goals in 58 games – marks him out as a phenomenon and the greatest centre-forward of his era."}, special: "Superstar" },
  { number: 11, name: 'Jørgen Strand Larsen', position: 'FW', age: 26, club: 'Crystal Palace', bio: {"es":"En 2017, un chico alto de Halden hizo las maletas y se fue a Milán. Strand Larsen, de 17 años, fue invitado a jugar cedido en el Primavera de Milán. Su entrenador en aquel momento: Gennaro Gattuso. El delantero causó una buena impresión, pero el Milan decidió no hacer permanente el traspaso. Ocho años después, en San Siro, de todos los lugares, el público local italiano está abandonando el estadio cuando Strand Larsen, ahora una estrella de la Premier League, irrumpe en la portería, dribla a Gianluca Mancini con facilidad y dispara a Gianluigi Donnarumma. El gol del 4-1 es tan icónico para Noruega como vergonzoso para Italia y su entrenador es... Gennaro Gattuso. Strand Larsen sería la primera opción para muchos países, pero no para Noruega, y está contento con su papel de respaldo. \"Erling [Haaland] es uno de mis mejores amigos y es ridículamente bueno\", dice el supersuplente de Noruega.","en":"In 2017 a tall boy from Halden packed his bags and left for Milan. The 17-year-old Strand Larsen was invited to play for Milan’s Primavera team on loan. Their coach at the time: Gennaro Gattuso. The striker made a good impression but Milan decided against making the transfer permanent. Fast forward eight years and at San Siro, of all places, the Italian home crowd is leaving the stadium as Strand Larsen, now a Premier League star, bursts through on goal, dribbles past Gianluca Mancini with ease and shoots past Gianluigi Donnarumma. The goal to make it 4-1 is as iconic for Norway as it is embarrassing for Italy and their coach is … Gennaro Gattuso. Strand Larsen would be the first choice for many countries but not Norway – and he is happy with his back-up role. “Erling [Haaland] is one of my best friends and he is ridiculously good,” says Norway’s supersub."} },
  { number: 20, name: 'Antonio Nusa', position: 'FW', age: 21, club: 'RB Leipzig', bio: {"es":"Entre todas las estrellas de la selección noruega, ninguna es más apreciada por los aficionados del estadio Ullevaal que Nusa. Cada vez que recibe el balón, se puede escuchar la anticipación del público, y casi siempre responde driblando a su oponente. Lo más destacado hasta el momento fue el gol de sus sueños en la victoria en casa por 3-0 sobre Italia, al que siguió con otra belleza en la escuadra en el partido de vuelta en San Siro. Hace dos años, cuando le preguntaron cómo llegó a ser tan bueno, dijo: “Vi clips de Neymar en YouTube y salí a intentar copiarlo”. Lo inusual de Nusa es que, hasta ahora, se ha desempeñado mejor en la selección que en su club. Ha estado con el RB Leipzig desde 2024, pero como es probable que más personas tomen nota del favorito de los fanáticos de Noruega en la Copa del Mundo, podría estar en juego un traslado a uno de los clubes más grandes de Europa.","en":"Among all the stars in the Norwegian national team, no one is more appreciated by the fans at Ullevaal Stadium than Nusa. Every time he gets the ball, the crowd's anticipation can be heard – and he almost always responds by dribbling past his opponent. The highlight so far was his dream goal in the 3-0 home victory over Italy, which he followed up with another beauty into the top corner in the return match at San Siro. Two years ago, when asked how he became so good, he said: “I watched clips of Neymar on YouTube and went out to try to copy him.” The unusual thing with Nusa is that, so far, he has been better for the national team than for his club sides. He has been with RB Leipzig since 2024 but as more people are likely to make note of Norway's fan favourite at the World Cup, a move to one of Europe’s biggest clubs could be on the cards."}, special: "Speedster" },
  { number: 21, name: 'Andreas Schjelderup', position: 'FW', age: 22, club: 'Benfica', bio: {"es":"A la edad de 13 años, Schjelderup ya tenía un plan trazado sobre cómo serían los próximos años de su vida. Iba a salir de Noruega en cuanto cumpliera 16 años y el mensaje a sus padres fue tajante: “No vendréis conmigo”. Schjelderup quería hacerlo a su manera. “Pensé que al unirse a mí tendrían que sacrificar la vida que llevaban en Bodø”. No pasó mucho tiempo antes de que los mejores clubes de Europa se dieran cuenta del talento de Schjelderup. Tuvo pruebas en el Ajax y el PSV, y visitó grandes clubes como el Barcelona, ​​el Liverpool y el Bayern de Múnich. Al final dejó Bodø/Glimt por la fábrica de talentos danesa FC Nordsjælland a la edad de... ya lo tienes: 16 años. Todo su sacrificio, determinación y trabajo duro dieron sus frutos. Desde que llegó al Benfica en 2023, se ha convertido en una estrella y marcó dos goles contra el Real Madrid en la notable victoria por 4-2 que llevó al Benfica a la ronda de playoffs de la Liga de Campeones. La Copa del Mundo podría ser el avance internacional de este extremo creativo y técnico.","en":"At the age of 13, Schjelderup already had a plan mapped out for how the next few years of his life would look. He was going to leave Norway as soon as he turned 16 and the message to his parents was blunt: “You are not coming with me.” Schjelderup wanted to do it his own way. “I thought that by joining me, they would have to sacrifice the life they lived in Bodø.” It did not take long before Europe’s top clubs were aware of Schjelderup’s talent. He had trials at Ajax and PSV, and visited big clubs such as Barcelona, Liverpool and Bayern Munich. In the end he left Bodø/Glimt for the Danish talent factory FC Nordsjælland at the age of … you’ve got it: 16. All his sacrifice, determination and hard work paid off. Since joining Benfica in 2023 he has become a star and scored twice against Real Madrid in the remarkable 4-2 win that took Benfica to the Champions League playoff round. The World Cup could be this creative and technical winger’s international breakthrough."} },
  { number: 22, name: 'Oscar Bobb', position: 'FW', age: 22, club: 'Fulham', bio: {"es":"La mayoría de los futbolistas se dan a conocer ante el público cuando se acercan a los 20 años. Algunos tienen que soportar la atención en su adolescencia. En Noruega, Bobb saltó a los titulares cuando tenía 12 años. Cuando la Copa de Noruega, el mayor torneo juvenil de fútbol, ​​se transmitió por televisión, era imposible no fijarse en el veloz centrocampista zurdo de Lyn, Oslo. \"Es como un pequeño Messi\", dijeron los comentaristas. Cuando Bobb volvió a las pantallas de televisión, fue para el Manchester City de Pep Guardiola. Pero tras ganar la liga en su primera temporada, se fracturó la pierna antes de la campaña 2024-25. Bobb comenzó la temporada 2025-26 en el once inicial, pero pronto cayó en desgracia y fue vendido al Fulham en enero por 27 millones de libras. También ha tenido momentos difíciles para la selección nacional, Ståle Solbakken le atacó después de un amistoso contra Nueva Zelanda. \"[Bobb] hoy careció de todo; pasó mucho tiempo con el balón, se posicionó de manera extraña y no acertó en el juego de presión. Si le preguntas a Oscar, creo que dirá que la primera mitad fue su actuación más débil con la selección nacional\". Fuera del terreno de juego, Bobb es una persona educada y modesta que, con miles de horas en la PlayStation, será el hombre a batir en los partidos del FC 26 en el hotel de los jugadores en Carolina del Norte.","en":"Most footballers become known to the public when they are approaching their 20s. Some have to endure attention in their early teens. In Norway, Bobb hit the headlines when he was 12. When the Norway Cup – football’s biggest youth tournament – was broadcast on TV, it was impossible not to notice the quick, left-footed midfielder from Lyn, Oslo. \"He is like a little Messi,\" the commentators said. When Bobb returned to TV screens, it was for Pep Guardiola's Manchester City. But after winning the league in his first season, he fractured his leg before the 2024-25 campaign. Bobb began the 2025-26 season in the starting XI yet soon found himself out of favour and he was sold to Fulham in January for £27m. He has had hard times for the national team too, Ståle Solbakken laying into him after a friendly against New Zealand. “[Bobb] lacked everything today; spent a long time with the ball, positioned himself strangely and didn’t hit the pressing game. If you ask Oscar, I think he’ll say that the first half was his weakest performance for the national team.” Off the pitch, Bobb is a polite and modest person who, with thousands of hours on the PlayStation, will be the man to beat in the FC 26 matches at the players' hotel in North Carolina."} },
  { number: 23, name: 'Jens Petter Hauge', position: 'FW', age: 26, club: 'Bodø/Glimt', bio: {"es":"“Es su mejor jugador”, dijo el técnico del Atlético de Madrid, Diego Simeone, sobre Hauge antes de que su equipo se enfrentara al Bodø/Glimt en enero. Y Simeone muchas veces tiene razón. Hauge tuvo un papel protagónico en la carrera de Glimt en la Liga de Campeones, anotando seis goles, incluidos goles contra el Manchester City y en ambos partidos contra el Inter en la ronda de playoffs. Hauge se ha recuperado de una mala racha en el Milán, al que se unió en 2020. Tampoco le funcionó en el Eintracht Frankfurt, pero ha estado jugando el mejor fútbol de su carrera desde que regresó a Glimt el año pasado. Mientras estuvo en Milán quedó impresionado por Zlatan Ibrahimovic, de 39 años, dentro y fuera del campo. Le dijo a CBS: \"Recuerdo que llegué al vestuario con una gorra nueva y Zlatan me dijo: '¿Estás haciendo pizzas o eres futbolista?' Me gusta cuando la gente bromea”.","en":"“He is their best player,” the Atlético Madrid manager, Diego Simeone, said of Hauge before his side took on Bodø/Glimt in January. And Simeone is often right. Hauge had a starring role in Glimt’s Champions League run, scoring six times, including goals against Manchester City and in both legs against Inter in the playoff round. Hauge has bounced back from a tough spell at Milan, whom he joined in 2020. It did not work out for him at Eintracht Frankfurt either but he has been playing the best football of his career since returning to Glimt last year. While at Milan he was impressed by the 39-year-old Zlatan Ibrahimovic – on and off the pitch. He told CBS: \"I remember I came to the dressing room with a new cap on and Zlatan said: 'Are you making pizzas or are you a footballer?' I like when people are joking.”"}, special: "Comeback kid" },
];

export const lineup = {
  formation: '4-3-3',
  startingXI: [1, 26, 3, 4, 5, 8, 10, 18, 7, 9, 20]
};
